// IMAGE CRAP
var MakeSprite = function(textureName){
	return new PIXI.Sprite(PIXI.loader.resources[textureName].texture);
}

// MovieClips!
var MakeMovieClip = function(resourceName){

	// Make it!
	var resources = PIXI.loader.resources;
	var resource = resources[resourceName];	
	var numFrames = Object.keys(resource.data.frames).length;
	var frames = [];
	for(var i=0; i<numFrames; i++){
		var str = "0000" + i; // FOUR leading zeroes
		str = str.substr(str.length-4);
		frames.push(PIXI.Texture.fromFrame(resourceName+str));
	}
	var mc = new PIXI.extras.MovieClip(frames);

	// Shtuff
	mc.gotoAndStop(0);
	mc.anchor.x = 0.5;
	mc.anchor.y = 1.0;

	// Return
	return mc;

};

Game.addToManifest({
	cursor: "sprites/misc/cursor.json"
}, true);

function Cursor(scene){

	var self = this;
	var mc = MakeMovieClip("cursor");
	mc.anchor.x = mc.anchor.y = 0;
	self.graphics = mc;
	mc.x = -100;
	mc.y = -100;

	self.click = false;
	Game.stage.mousemove = function(mouseData){
	    var pos = mouseData.data.global;
	    mc.x = pos.x+1;
	    mc.y = pos.y+1;
	};
	Game.stage.mousedown = function(mouseData){
		self.click = true;
	};
	Game.stage.mouseup = function(mouseData){
		self.click = false;
	};

	var doubles = 0;
	self.update = function(isHover){

		doubles = (doubles+1)%2; // animate on doubles!
		if(doubles!=0) return;

		if(self.click){
			mc.gotoAndStop(4);
		}else{
			if(isHover){
				if(mc.currentFrame<3) mc.gotoAndStop(mc.currentFrame+1);
			}else{
				if(mc.currentFrame>0) mc.gotoAndStop(mc.currentFrame-1);
			}
		}

	};

}

